var window = new PriorityQueue<Msg, long>();       // priority = sequence number
await foreach (var msg in input.Reader.ReadAllAsync(ct)) {
    window.Enqueue(msg, msg.Seq);
    gap.CancelAfter(gapTimeout);                   // deadline for the head
    while (window.TryPeek(out var head, out var seq) &&
           (seq == expected || gap.IsCancellationRequested)) {
        window.Dequeue();
        await output.Writer.WriteAsync(head, ct);  // single consumer keeps order
        expected = seq + 1;
    }
}
